    x: 8.2, y: 1.2, w: 1.8, h: 1.8, fill: { color: theme.accent, transparency: 50 }
  });

  // Main title
  slide.addText("DiaTool-DPO", {
    x: 0.6, y: 1.0, w: 7, h: 1.2,
    fontSize: 52, fontFace: "Georgia", color: "FFFFFF", bold: true, margin: 0
  });

  // Subtitle
  slide.addText("Enhancing Tool-Augmented LLM Dialogue\nvia Direct Preference Optimization", {
    x: 0.6, y: 2.3, w: 7.5, h: 1.0,
    fontSize: 22, fontFace: "Calibri", color: theme.light, margin: 0
  });

  // Tagline
  slide.addText("Automatic paired trajectory construction for improving TA-LLM slot-filling and tool call rejection — without human labeling", {
    x: 0.6, y: 3.6, w: 7, h: 0.7,
    fontSize: 13, fontFace: "Calibri", color: theme.accent, margin: 0
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: 10, h: 0.625, fill: { color: theme.secondary, transparency: 40 }
  });
  slide.addText("arXiv:2504.02882  |  ML Research & NLP Engineering", {
    x: 0.6, y: 5.05, w: 8, h: 0.5,
    fontSize: 11, fontFace: "Calibri", color: theme.light, margin: 0
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

