const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 2, title: 'Problem & Motivation' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("SFT Alone Fails to Teach Slot-Filling and Tool Rejection", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  // Context box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.15, w: 9, h: 0.7, fill: { color: theme.light, transparency: 70 }
  });
  slide.addText("Tool-Augmented LLMs must decide whether to ask follow-up questions, make a tool call, or reject inappropriate requests. SFT with expert trajectories alone has critical limitations.", {
    x: 0.65, y: 1.2, w: 8.7, h: 0.6,
    fontSize: 13, fontFace: "Calibri", color: theme.primary, margin: 0
  });

  // Three failure modes as cards
  const cards = [
    { title: "Missing Follow-ups", desc: "Model skips asking for required parameters, proceeding with incomplete information", icon: "?" },
    { title: "Hallucinated Tool Calls", desc: "Model fabricates tool invocations with incorrect or imagined arguments", icon: "!" },
    { title: "Failed Rejections", desc: "Model attempts tool calls for out-of-scope requests instead of declining", icon: "✕" }
  ];

  const cardW = 2.8, cardH = 2.2, startX = 0.5, startY = 2.2, gap = 0.2;

  cards.forEach((card, i) => {
    const cx = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: startY, w: cardW, h: cardH,
      fill: { color: theme.primary }, rectRadius: 0.03
    });

    // Icon circle
    slide.addShape(pres.shapes.OVAL, {
      x: cx + 0.15, y: startY + 0.2, w: 0.5, h: 0.5, fill: { color: theme.accent }
    });
    slide.addText(card.icon, {
      x: cx + 0.15, y: startY + 0.2, w: 0.5, h: 0.5,
