const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 3, title: '5-State MDP' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("Modeling TA-LLM Dialogue as a 5-State MDP", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  // 5 states as a horizontal process flow
  const states = [
    { num: "S1", label: "Initial", desc: "No history;\nreject out-of-scope" },
    { num: "S2", label: "Tool Selected\nw/o Slots", desc: "Tool identified;\nparams missing" },
    { num: "S3", label: "Tool Selected\nw/ Slots", desc: "All arguments\ndetermined" },
    { num: "S4", label: "Wait for\nResponse", desc: "Tool call\nexecuted" },
    { num: "S5", label: "Complete", desc: "Results received;\ncompletion sent" }
  ];

  const boxW = 1.6, boxH = 1.4, startX = 0.4, y = 1.3, gap = 0.35;

  states.forEach((s, i) => {
    const cx = startX + i * (boxW + gap);
    // State box
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: y, w: boxW, h: boxH,
      fill: { color: i === 0 || i === 4 ? theme.primary : theme.secondary },
      rectRadius: 0.03
    });
    // State number
    slide.addText(s.num, {
      x: cx, y: y + 0.1, w: boxW, h: 0.35,
      fontSize: 18, fontFace: "Georgia", color: theme.accent, bold: true, align: "center", margin: 0
    });
    // State label
    slide.addText(s.label, {
      x: cx + 0.1, y: y + 0.45, w: boxW - 0.2, h: 0.45,
      fontSize: 11, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
    });
    // Desc
    slide.addText(s.desc, {
      x: cx + 0.1, y: y + 0.9, w: boxW - 0.2, h: 0.4,
      fontSize: 9, fontFace: "Calibri", color: theme.light, align: "center", valign: "top", margin: 0
    });

    // Arrow between boxes
    if (i < 4) {
      slide.addShape(pres.shapes.LINE, {
        x: cx + boxW, y: y + boxH / 2, w: gap, h: 0,
        line: { color: theme.accent, width: 2 }
      });
      slide.addText("\u25B6", {
        x: cx + boxW + gap * 0.3, y: y + boxH / 2 - 0.15, w: 0.3, h: 0.3,
        fontSize: 10, color: theme.accent, align: "center", valign: "middle", margin: 0
      });
    }
  });

  // Key transitions description
  const transY = 3.1;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: transY, w: 9, h: 2.1, fill: { color: theme.light, transparency: 75 }
  });

  slide.addText("Key Transitions", {
    x: 0.7, y: transY + 0.1, w: 4, h: 0.35,
    fontSize: 16, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0
  });

  const transitions = [
    { label: "S1 → S3 → S4 → S5", desc: "Complete query — all required arguments present, direct tool call" },
    { label: "S1 → (S2×N) → S3 → S4 → S5", desc: "Incomplete query — slot-filling QA repeats N times to gather missing parameters" },
    { label: "S1 → S1", desc: "Out-of-scope query — no suitable tool available, request rejected" }
  ];

  transitions.forEach((t, i) => {
    slide.addText(t.label, {
      x: 0.7, y: transY + 0.55 + i * 0.5, w: 2.8, h: 0.4,
      fontSize: 12, fontFace: "Consolas", color: theme.secondary, bold: true, margin: 0
    });
    slide.addText(t.desc, {
      x: 3.6, y: transY + 0.55 + i * 0.5, w: 5.8, h: 0.4,
      fontSize: 12, fontFace: "Calibri", color: theme.primary, margin: 0
    });
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

