const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 4, title: 'Three Query Types' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("Three Query Types Define Distinct State Trajectories", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  // Table header row
  const headerOpts = { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 13, fontFace: "Calibri", align: "center", valign: "middle" };
  const cellOpts = { fill: { color: "FFFFFF" }, color: theme.primary, fontSize: 12, fontFace: "Calibri", valign: "middle" };
  const altCellOpts = { fill: { color: theme.light, transparency: 70 }, color: theme.primary, fontSize: 12, fontFace: "Calibri", valign: "middle" };

  const tableData = [
    [
      { text: "Query Type", options: { ...headerOpts } },
      { text: "State Trajectory", options: { ...headerOpts } },
      { text: "Scenario", options: { ...headerOpts } },
      { text: "Example", options: { ...headerOpts } }
    ],
    [
      { text: "Type 1\nSufficient Info", options: { ...cellOpts, align: "center", bold: true } },
      { text: "1 → 3 → 4 → 5", options: { ...cellOpts, fontFace: "Consolas", align: "center" } },
      { text: "Query contains all required arguments. No slot-filling needed.", options: { ...cellOpts } },
      { text: "\"Book a flight from NYC to LA on Dec 25\" — all parameters present, direct tool call", options: { ...cellOpts, fontSize: 11 } }
    ],
    [
      { text: "Type 2\nIncomplete Info", options: { ...altCellOpts, align: "center", bold: true } },
      { text: "1 → (2×N) → 3 → 4 → 5", options: { ...altCellOpts, fontFace: "Consolas", align: "center" } },
      { text: "Query lacks some arguments. Slot-filling QA repeats N times until all fields gathered.", options: { ...altCellOpts } },
      { text: "\"Book a flight to LA\" — missing date & origin, model asks follow-up questions", options: { ...altCellOpts, fontSize: 11 } }
    ],
    [
      { text: "Type 3\nOut-of-Scope", options: { ...cellOpts, align: "center", bold: true } },
      { text: "1 → 1", options: { ...cellOpts, fontFace: "Consolas", align: "center" } },
      { text: "Requested functionality is unavailable. Tool call must be rejected.", options: { ...cellOpts } },
      { text: "\"What's the meaning of life?\" — no suitable tool available, model returns rejection", options: { ...cellOpts, fontSize: 11 } }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.15, w: 9, h: 2.5,
    colW: [1.5, 2.0, 2.5, 3.0],
    border: { pt: 0.5, color: theme.light },
    rowH: [0.45, 0.65, 0.65, 0.65]
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.0, w: 9, h: 1.0, fill: { color: theme.primary }
  });
  slide.addText("KEY INSIGHT", {
    x: 0.7, y: 4.1, w: 2, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: theme.accent, bold: true, margin: 0
  });
  slide.addText("This 3-type classification, combined with the 5-state MDP, enables systematic construction of preference pairs for DPO training — each query type defines which trajectories are correct vs. incorrect.", {
    x: 0.7, y: 4.4, w: 8.5, h: 0.5,
    fontSize: 13, fontFace: "Calibri", color: "FFFFFF", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

