const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 5, title: 'Dataset Construction' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("Automatic Paired Trajectory Construction Without Human Labels", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  const hOpts = { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle" };
  const cOpts = (alt) => ({ fill: { color: alt ? theme.light : "FFFFFF", transparency: alt ? 70 : 0 }, color: theme.primary, fontSize: 9.5, fontFace: "Calibri", valign: "middle", align: "center" });

  const rows = [
    [
      { text: "Query", options: hOpts },
      { text: "Chosen Trajectory", options: hOpts },
      { text: "Rejected Trajectory", options: hOpts },
      { text: "Learning Lesson", options: hOpts },
      { text: "Count", options: hOpts },
      { text: "Difficulty", options: hOpts }
    ],
    [{ text: "Type 1", options: cOpts(false) }, { text: "1→3→4→5", options: { ...cOpts(false), fontFace: "Consolas" } }, { text: "1→2→3→4→5", options: { ...cOpts(false), fontFace: "Consolas" } }, { text: "Prevent redundant slot-filling", options: { ...cOpts(false), align: "left" } }, { text: "2,089", options: cOpts(false) }, { text: "Easy", options: cOpts(false) }],
    [{ text: "Type 1", options: cOpts(true) }, { text: "1→3→4→5", options: { ...cOpts(true), fontFace: "Consolas" } }, { text: "1→(2×N)→3→4→5", options: { ...cOpts(true), fontFace: "Consolas" } }, { text: "Prevent redundant slot-filling", options: { ...cOpts(true), align: "left" } }, { text: "562 / 2,530", options: cOpts(true) }, { text: "Hard", options: cOpts(true) }],
    [{ text: "Type 1", options: cOpts(false) }, { text: "1→3→4→5", options: { ...cOpts(false), fontFace: "Consolas" } }, { text: "1→1", options: { ...cOpts(false), fontFace: "Consolas" } }, { text: "Tool call accept", options: { ...cOpts(false), align: "left" } }, { text: "2,090 / 562", options: cOpts(false) }, { text: "Easy/Hard", options: cOpts(false) }],
    [{ text: "Type 2", options: cOpts(true) }, { text: "1→2→3→4→5", options: { ...cOpts(true), fontFace: "Consolas" } }, { text: "1→3→4→5", options: { ...cOpts(true), fontFace: "Consolas" } }, { text: "Prevent slot hallucination", options: { ...cOpts(true), align: "left" } }, { text: "2,089", options: cOpts(true) }, { text: "Easy", options: cOpts(true) }],
    [{ text: "Type 2", options: cOpts(false) }, { text: "1→(2×N)→3→4→5", options: { ...cOpts(false), fontFace: "Consolas" } }, { text: "1→3→4→5 / 1→(2×M)", options: { ...cOpts(false), fontFace: "Consolas" } }, { text: "Prevent slot hallucination", options: { ...cOpts(false), align: "left" } }, { text: "562 / 2,530", options: cOpts(false) }, { text: "Hard", options: cOpts(false) }],
    [{ text: "Type 3", options: cOpts(true) }, { text: "1→1", options: { ...cOpts(true), fontFace: "Consolas" } }, { text: "1→3→4 / 1→(2×N)→3→4", options: { ...cOpts(true), fontFace: "Consolas" } }, { text: "Tool call reject", options: { ...cOpts(true), align: "left" } }, { text: "567 / 562", options: cOpts(true) }, { text: "Hard", options: cOpts(true) }],
  ];

  slide.addTable(rows, {
    x: 0.3, y: 1.1, w: 9.4,
    colW: [0.8, 1.5, 1.8, 2.1, 1.2, 1.0],
    border: { pt: 0.5, color: theme.light },
    rowH: [0.4, 0.4, 0.4, 0.4, 0.4, 0.4, 0.4]
  });

  // Bottom callouts
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.15, w: 4.2, h: 1.0, fill: { color: theme.secondary }
  });
  slide.addText("Automatic Construction", {
    x: 0.65, y: 4.2, w: 3.9, h: 0.3,
    fontSize: 13, fontFace: "Georgia", color: theme.accent, bold: true, margin: 0
  });
  slide.addText("No human labeling required. Pairs are generated from the MDP structure and query type classification.", {
    x: 0.65, y: 4.55, w: 3.9, h: 0.55,
    fontSize: 11, fontFace: "Calibri", color: "FFFFFF", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.0, y: 4.15, w: 4.5, h: 1.0, fill: { color: theme.secondary }
  });
  slide.addText("Learning Signal", {
    x: 5.15, y: 4.2, w: 4.2, h: 0.3,
    fontSize: 13, fontFace: "Georgia", color: theme.accent, bold: true, margin: 0
  });
  slide.addText("Each pair teaches a specific lesson: prevent redundant questions, prevent hallucination, or enforce rejection of unavailable tools.", {
    x: 5.15, y: 4.55, w: 4.2, h: 0.55,
    fontSize: 11, fontFace: "Calibri", color: "FFFFFF", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

