const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 6, title: 'Benchmark Results' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("SFT + DiaTool-DPO Achieves Best Macro Average Across All Models", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  slide.addText("FunctionChat-Bench Results", {
    x: 0.5, y: 0.9, w: 4, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: theme.secondary, margin: 0
  });

  const hOpts = { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle" };
  const c = (val, best, alt) => {
    const opts = { fill: { color: alt ? theme.light : "FFFFFF", transparency: alt ? 70 : 0 }, color: theme.primary, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle" };
    if (best) { opts.bold = true; opts.color = theme.secondary; }
    return { text: val, options: opts };
  };
  const mLabel = (t, alt) => ({ text: t, options: { fill: { color: alt ? theme.light : "FFFFFF", transparency: alt ? 70 : 0 }, color: theme.primary, fontSize: 10, fontFace: "Calibri", valign: "middle", bold: true } });

  const rows = [
    [
      { text: "Model", options: hOpts },
      { text: "Method", options: hOpts },
      { text: "Call", options: hOpts },
      { text: "Completion", options: hOpts },
      { text: "Slot", options: hOpts },
      { text: "Relevance", options: hOpts },
      { text: "Micro Avg", options: hOpts },
      { text: "Macro Avg", options: hOpts }
    ],
    // Prop.-8B
    [mLabel("Prop.-8B", false), mLabel("DPO-only", false), c("0.314",false,false), c("0.700",false,false), c("0.833",true,false), c("0.609",false,false), c("0.575",false,false), c("0.614",false,false)],
    [mLabel("", true), mLabel("SFT-only", true), c("0.900",true,true), c("0.916",false,true), c("0.694",false,true), c("0.913",true,true), c("0.870",false,true), c("0.856",false,true)],
    [mLabel("", false), mLabel("SFT+DPO", false), c("0.886",false,false), c("0.929",true,false), c("0.833",true,false), c("0.826",false,false), c("0.884",true,false), c("0.868",true,false)],
    // Prop.-3.1B
    [mLabel("Prop.-3.1B", true), mLabel("DPO-only", true), c("0.357",false,true), c("0.551",false,true), c("0.528",false,true), c("0.391",false,true), c("0.455",false,true), c("0.457",false,true)],
    [mLabel("", false), mLabel("SFT-only", false), c("0.771",true,false), c("0.817",false,false), c("0.750",false,false), c("0.826",true,false), c("0.790",true,false), c("0.791",false,false)],
    [mLabel("", true), mLabel("SFT+DPO", true), c("0.743",false,true), c("0.871",true,true), c("0.833",true,true), c("0.826",true,true), c("0.765",false,true), c("0.818",true,true)],
    // LLaMA-3-8B
    [mLabel("LLaMA-3-8B", false), mLabel("DPO-only", false), c("0.029",false,false), c("0.449",false,false), c("0.056",false,false), c("0.261",false,false), c("0.205",false,false), c("0.199",false,false)],
    [mLabel("", true), mLabel("SFT-only", true), c("0.843",false,true), c("0.957",true,true), c("0.639",false,true), c("0.826",false,true), c("0.844",false,true), c("0.816",false,true)],
    [mLabel("", false), mLabel("SFT+DPO", false), c("0.857",true,false), c("0.929",false,false), c("0.917",true,false), c("0.913",true,false), c("0.905",true,false), c("0.904",true,false)],
  ];

  slide.addTable(rows, {
    x: 0.3, y: 1.25, w: 9.4,
    colW: [1.1, 1.0, 0.85, 1.05, 0.85, 1.0, 0.95, 0.95],
    border: { pt: 0.5, color: theme.light },
    rowH: [0.35, 0.33, 0.33, 0.33, 0.33, 0.33, 0.33, 0.33, 0.33, 0.33]
  });

  // Highlight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 9, h: 0.55, fill: { color: theme.accent, transparency: 70 }
  });
  slide.addText("SFT + DiaTool-DPO consistently achieves the highest Macro Average across all model sizes, demonstrating that DPO complements SFT for balanced dialogue control performance.", {
    x: 0.65, y: 4.8, w: 8.7, h: 0.45,
    fontSize: 12, fontFace: "Calibri", color: theme.primary, margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

