const slideConfig = { type: 'content', index: 7, title: 'LLaMA-3-8B Gains' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  slide.addText("LLaMA-3-8B: +43.5% Slot Accuracy and +10.5% Relevance", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Georgia", color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  slide.addText("Impact of adding DiaTool-DPO to SFT training on LLaMA-3-8B", {
    x: 0.5, y: 0.9, w: 6, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: theme.secondary, margin: 0
  });

  // Bar chart comparing SFT-only vs SFT+DPO on all metrics
  slide.addChart(pres.charts.BAR, [
    {
      name: "SFT-only",
      labels: ["Call", "Completion", "Slot", "Relevance", "Micro Avg", "Macro Avg"],
      values: [0.843, 0.957, 0.639, 0.826, 0.844, 0.816]
    },
    {
      name: "SFT + DiaTool-DPO",
      labels: ["Call", "Completion", "Slot", "Relevance", "Micro Avg", "Macro Avg"],
      values: [0.857, 0.929, 0.917, 0.913, 0.905, 0.904]
    }
  ], {
    x: 0.5, y: 1.4, w: 5.5, h: 3.5,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [theme.light, theme.accent],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 9,
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: theme.secondary,
    valAxisMinVal: 0,
    valAxisMaxVal: 1.0,
    valGridLine: { color: "E0E0E0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendFontSize: 10,
    legendColor: theme.primary
