const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'summary', index: 8, title: 'Key Takeaways' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Key Takeaways", {
    x: 0.6, y: 0.35, w: 8, h: 0.7,
    fontSize: 32, fontFace: "Georgia", color: "FFFFFF", bold: true, margin: 0
  });
  slide.addText("RL-Based Dialogue Control for Production TA-LLMs", {
    x: 0.6, y: 1.0, w: 8, h: 0.35,
    fontSize: 14, fontFace: "Calibri", color: theme.accent, margin: 0
  });

  const takeaways = [
    { num: "01", title: "MDP Formulation Enables Systematic Pairing", desc: "Defining 5 internal states and 3 query types allows automatic generation of chosen/rejected trajectory pairs without human annotation." },
    { num: "02", title: "DPO Complements SFT, Not Replaces It", desc: "DiaTool-DPO alone performs poorly. Combined with SFT, it consistently achieves the best balanced Macro Average across all model sizes." },
    { num: "03", title: "Largest Gains in Slot-Filling and Tool Rejection", desc: "LLaMA-3-8B improves Slot accuracy by +43.5% and Relevance by +10.5% over SFT-only, reaching near GPT-4o performance." },
    { num: "04", title: "Language-Agnostic and Production-Ready", desc: "While primary experiments were in Korean, the method generalizes to English — opening broad applicability for production TA-LLMs." }
  ];

  const startY = 1.6, itemH = 0.85, gap = 0.12;

  takeaways.forEach((t, i) => {
    const iy = startY + i * (itemH + gap);
    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: iy, w: 0.55, h: 0.55, fill: { color: theme.accent }, rectRadius: 0.03
    });
    slide.addText(t.num, {
      x: 0.6, y: iy, w: 0.55, h: 0.55,
      fontSize: 16, fontFace: "Georgia", color: theme.primary, bold: true, align: "center", valign: "middle"
    });
    // Title
